import * as sessionStore from '@web-whisper/session-store';
import { transcribeAudio } from '@web-whisper/transcription-client';
import type { TranscriptionContextSettings } from './types';
import { orderedSnips, promptChainFromTranscripts } from './transcriptionContext';

export { promptChainFromTranscripts } from './transcriptionContext';
import {
  analyzeVolumeForSession,
  proposeSnipsForSession,
} from '@web-whisper/volume-analyzer';
import { assembleSnipTranscriptionBlob } from './assembleSnipAudio';
import { emitTranscriptionEvent } from './transcriptionEvents';
import type { SnipRecord, TranscriptRecord } from './types';

export { buildTranscriptText } from './transcriptText';

export type TranscribeProgress = {
  phase: 'analyzing' | 'transcribing';
  completed: number;
  total: number;
};

export type TranscribeOutcome = {
  total: number;
  completed: number;
  failed: number;
  empty?: boolean;
  stopReason?: string;
  failures: Array<{ snipId: string; error: string }>;
};

export type LiveIngestResult = {
  snips: SnipRecord[];
  transcripts: TranscriptRecord[];
  failures: Array<{ snipId: string; error: string }>;
};

const ingestChains = new Map<string, Promise<unknown>>();
const ingestInFlight = new Set<string>();
const transcribingSnips = new Set<string>();
const transcribeInFlight = new Map<string, number>();

function beginCountedWork(bag: Map<string, number>, sessionId: string) {
  bag.set(sessionId, (bag.get(sessionId) ?? 0) + 1);
}

function endCountedWork(bag: Map<string, number>, sessionId: string) {
  const next = (bag.get(sessionId) ?? 1) - 1;
  if (next <= 0) bag.delete(sessionId);
  else bag.set(sessionId, next);
}

function withSessionLock<T>(sessionId: string, fn: () => Promise<T>): Promise<T> {
  const previous = ingestChains.get(sessionId) ?? Promise.resolve();
  ingestInFlight.add(sessionId);
  const next = previous.catch(() => undefined).then(fn);
  ingestChains.set(sessionId, next);
  void next.finally(() => {
    if (ingestChains.get(sessionId) === next) {
      ingestInFlight.delete(sessionId);
    }
  });
  return next;
}

/** True while live ingest or leftover transcription is in flight for this take. */
export function isSessionWorkPending(sessionId: string): boolean {
  if (ingestInFlight.has(sessionId)) return true;
  return (transcribeInFlight.get(sessionId) ?? 0) > 0;
}

async function assembleSnipBlob(
  snip: SnipRecord,
  sessionChunks: Array<{ id: string; startTime: number; endTime: number; duration?: number }>
): Promise<Blob> {
  const assembled = await assembleSnipTranscriptionBlob(snip, {
    sessionChunks,
    getChunk: (chunkId) => sessionStore.getChunk(chunkId),
  });
  return assembled.blob;
}

async function loadDurableState(sessionId: string): Promise<{
  snips: SnipRecord[];
  transcripts: TranscriptRecord[];
}> {
  const snipsResult = await sessionStore.getSnipsForSession(sessionId);
  const transcriptsResult = await sessionStore.getTranscriptsForSession(sessionId);
  return {
    snips: (snipsResult.snips || []) as SnipRecord[],
    transcripts: (transcriptsResult.transcripts || []) as TranscriptRecord[],
  };
}

/**
 * Concatenate durable snip transcripts for the live overlay (no timestamps).
 */
export function overlayTranscriptText(
  snips: SnipRecord[],
  transcripts: TranscriptRecord[]
): string {
  const bySnip = new Map(transcripts.map((item) => [item.snipId, item.text]));
  return snips
    .map((snip) => (bySnip.get(snip.id) || '').trim())
    .filter((text) => text.length > 0)
    .join(' ')
    .trim();
}

export async function ensureSnips(sessionId: string): Promise<SnipRecord[]> {
  const analysis = await analyzeVolumeForSession(sessionId);
  if (!analysis.success) {
    const existing = await sessionStore.getSnipsForSession(sessionId);
    if (existing.snips?.length) return existing.snips as SnipRecord[];
    throw new Error(analysis.error || 'Volume analysis failed');
  }
  // Growing window: proposeSnipsForSession freezes stored snips and sets
  // windowStartTime = last snip end so uncovered audio can become new snips.
  const proposed = await proposeSnipsForSession(sessionId, { includeTrailing: true });
  if (!proposed.success) {
    const existing = await sessionStore.getSnipsForSession(sessionId);
    if (existing.snips?.length) return existing.snips as SnipRecord[];
    throw new Error(proposed.error || 'Snip proposal failed');
  }
  const next = await sessionStore.getSnipsForSession(sessionId);
  return (next.snips || []) as SnipRecord[];
}

async function transcribePendingSnips(
  snips: SnipRecord[],
  apiKey: string,
  already: TranscriptRecord[],
  onProgress?: (progress: TranscribeProgress) => void,
  onTranscriptWritten?: () => Promise<void> | void,
  context: TranscriptionContextSettings = { contextEnabled: true, vocabulary: '' }
): Promise<{
  completed: number;
  failed: number;
  stopReason?: string;
  failures: Array<{ snipId: string; error: string }>;
}> {
  const done = new Set(
    already.filter((item) => item.text?.trim()).map((item) => item.snipId)
  );

  const ordered = orderedSnips(snips);
  const targets = ordered.filter((snip) => !done.has(snip.id) && !transcribingSnips.has(snip.id));
  const contextEnabled = context.contextEnabled !== false;
  const chain = promptChainFromTranscripts(
    ordered.filter((snip) => done.has(snip.id)),
    already,
    context
  );
  let completed = snips.length - targets.length;
  let failed = 0;
  const failures: Array<{ snipId: string; error: string }> = [];
  const sessionId = targets[0]?.sessionId || snips[0]?.sessionId;
  const listed = sessionId ? await sessionStore.getChunksForSession(sessionId) : { chunks: [] };
  const sessionChunks = listed.chunks || [];

  for (const snip of targets) {
    onProgress?.({
      phase: 'transcribing',
      completed,
      total: snips.length,
    });
    transcribingSnips.add(snip.id);
    try {
      const blob = await assembleSnipBlob(snip, sessionChunks);
      if (blob.size === 0) {
        failed += 1;
        failures.push({ snipId: snip.id, error: 'No audio for snip' });
        continue;
      }
      // One Groq call per snip. `blob` is assembleSnipTranscriptionBlob output
      // (time-trimmed snip audio), not a raw 4s chunk and not the session tape.
      // Serial: this request starts after the previous snip resolved so the
      // Whisper prompt can use that tail (or vocabulary only if poisoned).
      const promptInfo = contextEnabled ? chain.promptForNext() : { prompt: '' };
      const result = await transcribeAudio(blob, {
        apiKey,
        mode: 'live',
        prompt: promptInfo.prompt,
        contextEnabled,
      });
      if (contextEnabled) {
        chain.observeResult(result);
      }
      if ('error' in result && result.error) {
        failed += 1;
        failures.push({ snipId: snip.id, error: result.error });
        if (result.error === 'Invalid API key' || result.error === 'Rate limit exceeded') {
          return {
            completed,
            failed,
            stopReason: result.error,
            failures,
          };
        }
        continue;
      }
      await sessionStore.writeTranscript(snip.id, result.text || '');
      completed += 1;
      emitTranscriptionEvent({
        type: 'snip-complete',
        sessionId: snip.sessionId,
        snipId: snip.id,
      });
      if (onTranscriptWritten) {
        await onTranscriptWritten();
      }
    } finally {
      transcribingSnips.delete(snip.id);
    }
  }

  return { completed, failed, failures };
}

/**
 * Original web-whisper live path: volume/snip on the growing session, persist
 * closed snips, transcribe each through transcription-client, write transcripts
 * to session-store. Overlay reads that durable state.
 *
 * While recording pass `{ includeTrailing: false }` so the in-progress tail is
 * not committed. After Stop pass `{ includeTrailing: true }` to seal the last snip.
 */
export function ingestGrowingSession(
  sessionId: string,
  options: {
    apiKey?: string | null;
    includeTrailing?: boolean;
    transcribe?: boolean;
    onTranscriptWritten?: () => Promise<void> | void;
    contextEnabled?: boolean;
    vocabulary?: string;
  } = {}
): Promise<LiveIngestResult> {
  return withSessionLock(sessionId, async () => {
    const includeTrailing = options.includeTrailing === true;
    const analysis = await analyzeVolumeForSession(sessionId);
    if (analysis.success) {
      await proposeSnipsForSession(sessionId, { includeTrailing });
    }

    let { snips, transcripts } = await loadDurableState(sessionId);
    const failures: Array<{ snipId: string; error: string }> = [];

    if (options.transcribe && options.apiKey) {
      const outcome = await transcribePendingSnips(
        snips,
        options.apiKey,
        transcripts,
        undefined,
        options.onTranscriptWritten,
        {
          contextEnabled: options.contextEnabled !== false,
          vocabulary: options.vocabulary || '',
        }
      );
      failures.push(...outcome.failures);
      ({ snips, transcripts } = await loadDurableState(sessionId));
      emitTranscriptionEvent({ type: 'transcription-finished', sessionId });
    }

    return { snips, transcripts, failures };
  });
}

export async function transcribeSession(
  sessionId: string,
  apiKey: string,
  onProgress: (progress: TranscribeProgress) => void,
  options?: {
    retryFailedOnly?: boolean;
    onTranscriptWritten?: () => Promise<void> | void;
    contextEnabled?: boolean;
    vocabulary?: string;
  }
): Promise<TranscribeOutcome> {
  beginCountedWork(transcribeInFlight, sessionId);
  try {
    return await transcribeSessionInner(sessionId, apiKey, onProgress, options);
  } finally {
    endCountedWork(transcribeInFlight, sessionId);
  }
}

async function transcribeSessionInner(
  sessionId: string,
  apiKey: string,
  onProgress: (progress: TranscribeProgress) => void,
  options?: {
    retryFailedOnly?: boolean;
    onTranscriptWritten?: () => Promise<void> | void;
    contextEnabled?: boolean;
    vocabulary?: string;
  }
): Promise<TranscribeOutcome> {
  onProgress({ phase: 'analyzing', completed: 0, total: 0 });
  // RETRY TX re-runs volume + proposeSnipsForSession so uncovered audio past
  // lastSnipEnd can become new snips (same live ingest window). It does not
  // only re-hit Groq on already-closed snips.
  const snips = await ensureSnips(sessionId);
  if (snips.length === 0) {
    return { total: 0, completed: 0, failed: 0, empty: true, failures: [] };
  }

  const transcriptsResult = await sessionStore.getTranscriptsForSession(sessionId);
  const transcripts: TranscriptRecord[] = transcriptsResult.transcripts || [];

  // RETRY TX / re-transcribe never throws away audio or existing transcripts.
  // Always skip snips that already have text; only missed/failed snips run.
  void options?.retryFailedOnly;
  const outcome = await transcribePendingSnips(
    snips,
    apiKey,
    transcripts,
    onProgress,
    options?.onTranscriptWritten,
    {
      contextEnabled: options?.contextEnabled !== false,
      vocabulary: options?.vocabulary || '',
    }
  );
  emitTranscriptionEvent({ type: 'transcription-finished', sessionId });
  return {
    total: snips.length,
    completed: outcome.completed,
    failed: outcome.failed,
    stopReason: outcome.stopReason,
    failures: outcome.failures,
  };
}
