import { useEffect, useState } from 'react';
import * as sessionStore from '@web-whisper/session-store';
import { validateKey } from '@web-whisper/transcription-client';
import { buildIdentityLines, readBuildIdentity } from '../buildIdentity';
import { ImportSessionZipControl } from '../components/ImportSessionZipControl';
import { useApp } from '../context';
import { isolationDemosHref } from '../isolationDemos';
import {
  LOG_LEVELS,
  LOG_PACKAGE_IDS,
  formatLogBytesLine,
  formatLogPackageSize,
  withPackageLogLevel,
  type LogLevel,
} from '../logSettings';
import { isSettingsLogLevelsScreenshot, readScreenshotMode } from '../screenshotMode';

const GROQ_CONSOLE = 'https://console.groq.com/keys';
const GROQ_PRICING = 'https://groq.com/pricing';
const GROQ_DOCS = 'https://console.groq.com/docs/quickstart';

export function SettingsModal() {
  const app = useApp();
  const [apiKey, setApiKey] = useState(app.settings.groqApiKey);
  const [cap, setCap] = useState(String(app.settings.storageCapMb));
  const [busy, setBusy] = useState(false);
  const [advancedOpen, setAdvancedOpen] = useState(() =>
    isSettingsLogLevelsScreenshot(readScreenshotMode())
  );
  const [logSizes, setLogSizes] = useState<{
    logBytes: number;
    byPackage: Record<string, { bytes: number; count: number }>;
  } | null>(null);

  useEffect(() => {
    setApiKey(app.settings.groqApiKey);
    setCap(String(app.settings.storageCapMb));
  }, [app.settings.groqApiKey, app.settings.storageCapMb]);

  useEffect(() => {
    let cancelled = false;
    void sessionStore.getLogByteSizes().then((sizes) => {
      if (cancelled || !sizes || sizes.error) return;
      setLogSizes({
        logBytes: sizes.logBytes || 0,
        byPackage: sizes.byPackage || {},
      });
    });
    return () => {
      cancelled = true;
    };
  }, [app.usedBytes]);

  async function checkKey(value: string) {
    const trimmed = value.trim();
    if (!trimmed) {
      app.persistKey('', false, 'Missing');
      return;
    }
    setBusy(true);
    try {
      const result = await validateKey(trimmed);
      if (result.valid) {
        app.persistKey(trimmed, true, 'Valid');
      } else {
        app.persistKey('', false, result.reason || 'Invalid');
      }
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="overlay" onClick={() => app.setSettingsOpen(false)}>
      <section className="sheet" onClick={(event) => event.stopPropagation()}>
        <div className="sheet-head">
          <h2>Settings</h2>
          <button className="text-btn" onClick={() => app.setSettingsOpen(false)}>
            Close
          </button>
        </div>
        <div className="sheet-body">
          <section className="section">
            <div className="section-head">
              <h3>Transcription</h3>
              {app.settings.keyValid ? (
                <button
                  className="chip enabled"
                  onClick={() => {
                    setApiKey('');
                    app.persistKey('', false, 'Missing');
                  }}
                >
                  ENABLE
                </button>
              ) : (
                <span className="chip disabled">DISABLED</span>
              )}
            </div>
            <p>
              Groq is a separate service (not this app). Their free account takes about a
              minute to set up, and this app auto-checks your key after you paste it.{' '}
              <a href={GROQ_DOCS} target="_blank" rel="noreferrer">
                It&apos;s easy to set up.
              </a>
            </p>
            <ol className="steps">
              <li>Create a free Groq account at console.groq.com</li>
              <li>Paste the key here</li>
              <li>Transcription turns on after validation</li>
            </ol>
            <label className="field">
              Groq API key
              <input
                type="password"
                placeholder="gsk_..."
                value={apiKey}
                autoComplete="off"
                onChange={(event) => setApiKey(event.target.value)}
                onBlur={() => void checkKey(apiKey)}
              />
            </label>
            <div className="key-row">
              <span className="tiny">
                Key status: {busy ? 'Checking' : app.settings.keyStatus}
              </span>
              <button className="recheck" onClick={() => void checkKey(apiKey)} disabled={busy}>
                Recheck key
              </button>
            </div>
            <p className="help">
              Need a key?{' '}
              <a href={GROQ_CONSOLE} target="_blank" rel="noreferrer">
                Create one in Groq Console
              </a>
              . Groq is a separate service with its own pricing.{' '}
              <a href={GROQ_PRICING} target="_blank" rel="noreferrer">
                See Groq pricing
              </a>
              .
            </p>
            <label className="check-row">
              <input
                type="checkbox"
                checked={app.settings.contextAwareTranscription}
                onChange={(event) =>
                  app.updateSetting('contextAwareTranscription', event.target.checked)
                }
              />
              Context-aware transcription
            </label>
            <p className="help">
              Each snip waits for the previous Groq result and sends a Whisper
              prompt: vocabulary first, then the tail of the transcript so far.
              That keeps spelling consistent across cuts. It is slower than
              sending snips in parallel.
            </p>
            <label className="field">
              Vocabulary
              <textarea
                rows={2}
                placeholder="Asana, Groq, BrainGraft, TeleLinux"
                value={app.settings.transcriptionVocabulary}
                onChange={(event) =>
                  app.updateSetting('transcriptionVocabulary', event.target.value)
                }
              />
            </label>
            <p className="help">
              Optional names and spellings to keep consistent. Left empty is fine.
            </p>
          </section>

          <section className="section">
            <h3>App</h3>
            <label className="check-row">
              <input
                type="checkbox"
                checked={app.settings.developerModeEnabled}
                onChange={(event) =>
                  app.updateSetting('developerModeEnabled', event.target.checked)
                }
              />
              Enable developer mode
            </label>
            {app.settings.developerModeEnabled ? (
              <>
                <div className="iso-demos-block">
                  <a
                    className="cta-outline isolation-demos-link"
                    href={isolationDemosHref()}
                    target="_blank"
                    rel="noreferrer"
                  >
                    Isolation Demos
                  </a>
                  <p className="help">
                    Package factory-floor demos on GitHub Pages. Each demo uses its own
                    storage namespace so it cannot corrupt PWA sessions.
                  </p>
                </div>
                <div className="settings-import-block">
                  <h4 className="settings-import-heading">Session archive</h4>
                  <p className="help settings-import-lead">
                    Debugging only. Import a session zip to recreate a take in this
                    browser.
                  </p>
                  <ImportSessionZipControl />
                </div>
              </>
            ) : null}
            <label className="field">
              Storage cap (MB)
              <input
                className="narrow"
                type="number"
                min={1}
                value={cap}
                onChange={(event) => setCap(event.target.value)}
                onBlur={() => {
                  const next = Math.max(1, Number(cap) || 200);
                  setCap(String(next));
                  app.updateSetting('storageCapMb', next);
                }}
              />
            </label>
            <p className="help">
              Maximum storage for session data. When this limit is reached, audio
              (and waveforms) for already-transcribed snips is removed so recording
              can continue. Transcripts are kept.
            </p>
            <details
              className="advanced-details"
              open={advancedOpen}
              onToggle={(event) => setAdvancedOpen(event.currentTarget.open)}
            >
              <summary>Advanced</summary>
              <p className="help">
                Per-package log levels. Default is info — debug stays off unless you
                turn it on. Sizes are approximate and refresh when you open Settings.
              </p>
              <p className="tiny log-sizes-total" data-testid="log-bytes-total">
                {logSizes ? formatLogBytesLine(logSizes.logBytes) : 'Measuring logs…'}
              </p>
              {logSizes
                ? LOG_PACKAGE_IDS.filter((packageId) => (logSizes.byPackage[packageId]?.bytes ?? 0) > 0).map(
                    (packageId) => (
                      <p key={packageId} className="tiny muted log-size-row">
                        {formatLogPackageSize(packageId, logSizes.byPackage[packageId])}
                      </p>
                    )
                  )
                : null}
              {LOG_PACKAGE_IDS.map((packageId) => (
                <label key={packageId} className="field log-level-field">
                  {packageId}
                  <select
                    className="log-level-select"
                    aria-label={`${packageId} log level`}
                    value={app.settings.logLevels[packageId]}
                    onChange={(event) =>
                      app.updateSetting(
                        'logLevels',
                        withPackageLogLevel(
                          app.settings.logLevels,
                          packageId,
                          event.target.value as LogLevel
                        )
                      )
                    }
                  >
                    {LOG_LEVELS.map((level) => (
                      <option key={level} value={level}>
                        {level}
                      </option>
                    ))}
                  </select>
                </label>
              ))}
            </details>
            <p className="build-identity" aria-label="App build identity">
              {buildIdentityLines(readBuildIdentity()).map((line) => (
                <span key={line}>{line}</span>
              ))}
            </p>
          </section>
        </div>
      </section>
    </div>
  );
}
